import { Box } from '@mui/material'
import {
    MDXEditor, codeBlockPlugin, codeMirrorPlugin, diffSourcePlugin,
    headingsPlugin, imagePlugin, linkDialogPlugin, linkPlugin, listsPlugin, markdownShortcutPlugin, quotePlugin,
    tablePlugin, thematicBreakPlugin, toolbarPlugin,
    type MDXEditorMethods, type ViewMode,
} from '@mdxeditor/editor'
import '@mdxeditor/editor/style.css'
import {
    forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef,
    type FocusEvent, type ReactNode,
} from 'react'
import type { ActionPlaceholder } from '../../data/action_placeholders'
import { useProjectState } from '../hooks/use_project_state'
import { dialogService } from '../../services/dialog_service'
import { useAppTheme } from '../../theme/use_app_theme'
import { markdownDocumentHistoryPlugin } from './markdown_document_history_realm_plugin'
import type { MarkdownDocumentHistoryStore } from './markdown_document_history_store'
import { MarkdownFormatToolbarControls } from './markdown_format_toolbar_controls'
import { markdownFileSearchPlugin } from './markdown_file_search_realm_plugin'
import { plainMarkdownPlugin } from './plain_markdown_realm_plugin'
import { markdownPlaceholderPlugin } from './markdown_placeholder_realm_plugin'
import { registerMarkdownEditorFlush } from './markdown_editor_flush'
import { markdownPastePlugin } from './markdown_paste_realm_plugin'
import type {
    ActiveMarkdownDocumentChangedDetail,
    MarkdownBindingKind,
    MarkdownDataSource,
    MarkdownDocumentTarget,
} from './markdown_data_source'

const DEFAULT_CODE_LANGUAGE = ''
const CODE_BLOCK_LANGUAGES = { '': 'Plain text', js: 'JavaScript', ts: 'TypeScript', tsx: 'TSX', bash: 'Shell' }
const EMPTY_PLACEHOLDERS: readonly ActionPlaceholder[] = []
const EMPTY_REPOSITORY_FILES: readonly string[] = []

export interface MarkdownEditorHandle {
    flush(): boolean
    getMarkdown(): string
    setMarkdown(markdown: string): void
}

interface MarkdownEditorPresentationProps {
    diffMarkdown?: string
    flushOnBlur?: boolean
    /** Omit format toolbar entirely. */
    hideToolbar?: boolean
    overlayContainer?: HTMLElement | null
    placeholders?: readonly ActionPlaceholder[]
    readOnly?: boolean
    toolbarContents?: () => ReactNode
    viewMode?: ViewMode
}

interface MarkdownEditorDataSourceProps extends MarkdownEditorPresentationProps {
    binding: MarkdownBindingKind
    dataSource: MarkdownDataSource
    historyStore: MarkdownDocumentHistoryStore
    markdown?: never
    onChange?: never
    onDirtyChange?: never
    onLiveChange?: never
}

interface MarkdownEditorLocalProps extends MarkdownEditorPresentationProps {
    binding?: never
    dataSource?: never
    historyStore?: never
    markdown: string
    onChange: (markdown: string) => void
    onDirtyChange?: (dirty: boolean) => void
    onLiveChange?: (markdown: string) => void
}

type MarkdownEditorProps = MarkdownEditorDataSourceProps | MarkdownEditorLocalProps

interface MarkdownDocumentSnapshot {
    target: MarkdownDocumentTarget | null
    markdown: string
}

interface MarkdownProcessingError {
    error: string
}

function initialDocument(props: MarkdownEditorProps): MarkdownDocumentSnapshot {
    if (!props.dataSource) return { target: null, markdown: props.markdown }

    const target = props.dataSource.getActiveTarget(props.binding)
    return { target, markdown: target ? props.dataSource.getMarkdown(target) : '' }
}

/** Reusable MDXEditor surface with local-buffer and persisted data-source modes. */
export const MarkdownEditor = forwardRef<MarkdownEditorHandle, MarkdownEditorProps>(function MarkdownEditor(props, ref) {
    const {
        flushOnBlur = false,
        diffMarkdown,
        hideToolbar = false,
        overlayContainer,
        placeholders = EMPTY_PLACEHOLDERS,
        readOnly = false,
        toolbarContents: customToolbarContents,
        viewMode,
    } = props
    const dataSource = props.dataSource
    const binding = props.binding
    const historyStore = props.historyStore
    const { snapshot } = useProjectState()
    const repositoryFiles = snapshot?.repositoryFiles ?? EMPTY_REPOSITORY_FILES
    const initialDocumentRef = useRef<MarkdownDocumentSnapshot | null>(null)
    if (!initialDocumentRef.current) initialDocumentRef.current = initialDocument(props)
    const initialDocumentSnapshot = initialDocumentRef.current
    const { markdownContentSx, mode } = useAppTheme()
    const editorRef = useRef<MDXEditorMethods>(null)
    const activeTargetRef = useRef(initialDocumentSnapshot.target)
    const latestMarkdownRef = useRef(initialDocumentSnapshot.markdown)
    const lastEmittedMarkdownRef = useRef(initialDocumentSnapshot.markdown)
    const dirtyBaselineEstablishedRef = useRef(false)
    const missingEditorReportedRef = useRef(false)
    const replacingMarkdownRef = useRef(false)
    const onChangeRef = useRef(props.onChange)
    const onDirtyChangeRef = useRef(props.onDirtyChange)
    const onLiveChangeRef = useRef(props.onLiveChange)
    const applyPendingDocumentChangeRef = useRef<() => void>(() => undefined)
    onChangeRef.current = props.onChange
    onDirtyChangeRef.current = props.onDirtyChange
    onLiveChangeRef.current = props.onLiveChange

    const setDirty = useCallback((dirty: boolean) => {
        onDirtyChangeRef.current?.(dirty)
    }, [])

    const flush = useCallback(() => {
        if (latestMarkdownRef.current === lastEmittedMarkdownRef.current) return true

        const activeTarget = activeTargetRef.current
        if (dataSource && binding) {
            if (!activeTarget) return true
            const committed = dataSource.commit(binding, activeTarget, latestMarkdownRef.current)
            if (!committed) return false
        } else {
            onChangeRef.current?.(latestMarkdownRef.current)
        }
        lastEmittedMarkdownRef.current = latestMarkdownRef.current
        setDirty(false)
        queueMicrotask(() => applyPendingDocumentChangeRef.current())

        return true
    }, [binding, dataSource, setDirty])

    const prepareDocumentSwitch = useCallback((detail: ActiveMarkdownDocumentChangedDetail, nextMarkdown: string) => {
        if (detail.discard) lastEmittedMarkdownRef.current = latestMarkdownRef.current
        if (!flush()) return null

        const currentMarkdown = latestMarkdownRef.current
        activeTargetRef.current = detail.target
        latestMarkdownRef.current = nextMarkdown
        lastEmittedMarkdownRef.current = nextMarkdown
        setDirty(false)

        return currentMarkdown
    }, [flush, setDirty])

    const completeDocumentSwitch = useCallback((normalizedMarkdown: string) => {
        latestMarkdownRef.current = normalizedMarkdown
        lastEmittedMarkdownRef.current = normalizedMarkdown
        setDirty(false)
    }, [setDirty])

    const getMarkdown = useCallback(() => editorRef.current?.getMarkdown() ?? latestMarkdownRef.current, [])
    const getTarget = useCallback(() => activeTargetRef.current, [])

    const replaceMarkdown = useCallback((markdown: string) => {
        replacingMarkdownRef.current = true
        editorRef.current?.setMarkdown(markdown)
        replacingMarkdownRef.current = false
    }, [])

    const setPendingDocumentChangeRetry = useCallback((retry: () => void) => {
        applyPendingDocumentChangeRef.current = retry
    }, [])

    const historyPluginConfig = useMemo(() => historyStore && binding && dataSource
        ? {
            binding,
            completeDocumentSwitch,
            dataSource,
            getTarget,
            getMarkdown,
            historyStore,
            prepareDocumentSwitch,
            replaceMarkdown,
            setPendingDocumentChangeRetry,
        }
        : null, [
        binding,
        completeDocumentSwitch,
        dataSource,
        getTarget,
        getMarkdown,
        historyStore,
        prepareDocumentSwitch,
        replaceMarkdown,
        setPendingDocumentChangeRetry,
    ])

    useEffect(() => {
        if (!editorRef.current) {
            if (!missingEditorReportedRef.current) {
                missingEditorReportedRef.current = true
                dialogService.error(new Error('Cannot baseline markdown before editor is mounted'), {fallbackMessage: 'Markdown editor could not be initialized'})
            }
            return
        }

        const normalizedMarkdown = editorRef.current.getMarkdown()
        latestMarkdownRef.current = normalizedMarkdown
        lastEmittedMarkdownRef.current = normalizedMarkdown
        dirtyBaselineEstablishedRef.current = true
    }, [])

    useEffect(() => {
        const unregister = registerMarkdownEditorFlush(flush)

        return () => {
            unregister()
            flush()
        }
    }, [flush])

    useImperativeHandle(ref, () => ({
        flush,
        getMarkdown: () => latestMarkdownRef.current,
        setMarkdown: (markdown: string) => {
            replaceMarkdown(markdown)
            latestMarkdownRef.current = markdown
            lastEmittedMarkdownRef.current = markdown
            setDirty(false)
        },
    }), [flush, replaceMarkdown, setDirty])

    const handleEditorChange = useCallback((markdown: string) => {
        if (replacingMarkdownRef.current || latestMarkdownRef.current === markdown) return

        latestMarkdownRef.current = markdown
        if (!dirtyBaselineEstablishedRef.current) return
        setDirty(markdown !== lastEmittedMarkdownRef.current)
        onLiveChangeRef.current?.(markdown)
        const activeTarget = activeTargetRef.current
        if (dataSource && binding && activeTarget) dataSource.edit(binding, activeTarget, markdown)
    }, [binding, dataSource, setDirty])

    const handleEditorError = useCallback(({ error }: MarkdownProcessingError) => {
        dialogService.error(new Error(error), { fallbackMessage: 'Markdown could not be parsed' })
    }, [])

    const handleBlur = (event: FocusEvent<HTMLDivElement>) => {
        if (!flushOnBlur || event.currentTarget.contains(event.relatedTarget)) return
        flush()
    }

    const insertMarkdown = useCallback((markdown: string) => {
        editorRef.current?.insertMarkdown(markdown)
    }, [])

    const defaultToolbarContents = useCallback(
        () => <MarkdownFormatToolbarControls overlayContainer={overlayContainer} placeholders={placeholders} />,
        [overlayContainer, placeholders],
    )
    const toolbarContents = customToolbarContents ?? defaultToolbarContents
    const editorSx = {
        ...markdownContentSx,
        '& .mdxeditor-toolbar': { bgcolor: 'background.paper', position: 'sticky', top: 0, zIndex: 1 },
    }
    const historyPlugin = historyPluginConfig ? markdownDocumentHistoryPlugin(historyPluginConfig) : null
    const plugins = [
        headingsPlugin(),
        listsPlugin(),
        quotePlugin(),
        thematicBreakPlugin(),
        linkPlugin(),
        linkDialogPlugin(),
        imagePlugin(),
        tablePlugin(),
        codeBlockPlugin({ defaultCodeBlockLanguage: DEFAULT_CODE_LANGUAGE }),
        codeMirrorPlugin({ codeBlockLanguages: CODE_BLOCK_LANGUAGES }),
        markdownShortcutPlugin(),
        plainMarkdownPlugin(),
        ...(viewMode ? [diffSourcePlugin({ diffMarkdown: diffMarkdown ?? '', viewMode })] : []),
        ...(hideToolbar ? [] : [toolbarPlugin({ toolbarContents })]),
        markdownPlaceholderPlugin({ overlayContainer, placeholders }),
        markdownFileSearchPlugin({ overlayContainer, repositoryFiles }),
        markdownPastePlugin({ insertMarkdown }),
        ...(historyPlugin ? [historyPlugin] : []),
    ]

    return (
        <Box data-sticky-toolbar onBlur={handleBlur} sx={editorSx}>
            <MDXEditor
                className={mode === 'dark' ? 'dark-theme' : 'light-theme'}
                contentEditableClassName="mdxeditor-content"
                markdown={initialDocumentSnapshot.markdown}
                onChange={handleEditorChange}
                onError={handleEditorError}
                overlayContainer={overlayContainer}
                plugins={plugins}
                readOnly={readOnly}
                ref={editorRef}
                suppressHtmlProcessing
                suppressSharedHistory={!!historyStore}
            />
        </Box>
    )
})

import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext'
import { useCellValue } from '@mdxeditor/editor'
import {
    COMMAND_PRIORITY_HIGH,
    PASTE_COMMAND,
    type PasteCommandType,
} from 'lexical'
import { useCallback, useEffect } from 'react'
import { useDialogError } from '../hooks/use_dialog_error'
import { markdownPasteConfig$ } from './markdown_paste_cell'

/** Imports plain clipboard content as Markdown at the current Lexical selection. */
export function MarkdownPastePlugin() {
    const config = useCellValue(markdownPasteConfig$)
    const [editor] = useLexicalComposerContext()
    const configError = config ? null : new Error('Cannot register Markdown paste without configuration')
    useDialogError(configError, 'Markdown paste is unavailable')

    const handlePaste = useCallback((event: PasteCommandType) => {
        if (!config || !('clipboardData' in event) || !event.clipboardData) return false

        const markdown = event.clipboardData.getData('text/markdown')
            || event.clipboardData.getData('text/plain')
        if (!markdown) return false

        event.preventDefault()
        config.insertMarkdown(markdown)
        return true
    }, [config])

    useEffect(
        () => editor.registerCommand(PASTE_COMMAND, handlePaste, COMMAND_PRIORITY_HIGH),
        [editor, handlePaste],
    )

    return null
}

import { addComposerChild$, realmPlugin } from '@mdxeditor/editor'
import { markdownPasteConfig$, type MarkdownPasteConfig } from './markdown_paste_cell'
import { MarkdownPastePlugin } from './markdown_paste_plugin'

/** Connects Markdown-aware clipboard handling to MDXEditor's Lexical editor. */
export const markdownPastePlugin = realmPlugin<MarkdownPasteConfig>({
    init(realm, params) {
        if (!params) throw new Error('Markdown paste plugin requires parameters')

        realm.register(markdownPasteConfig$)
        realm.pub(markdownPasteConfig$, params)
        realm.pub(addComposerChild$, MarkdownPastePlugin)
    },
    update(realm, params) {
        if (!params) throw new Error('Markdown paste plugin requires parameters')

        realm.pub(markdownPasteConfig$, params)
    },
})

import { Cell } from '@mdxeditor/editor'

export interface MarkdownPasteConfig {
    insertMarkdown: (markdown: string) => void
}

export const markdownPasteConfig$ = Cell<MarkdownPasteConfig | null>(null)

import { addImportVisitor$, realmPlugin } from '@mdxeditor/editor'
import { $createTextNode } from 'lexical'

/** Treats raw HTML-like Markdown nodes as text while MDX/HTML processing is disabled. */
export const plainMarkdownPlugin = realmPlugin({
    init(realm) {
        realm.pub(addImportVisitor$, {
            testNode: 'html',
            visitNode({ actions, mdastNode }) {
                if (mdastNode.type !== 'html') throw new Error('Plain Markdown HTML visitor received a non-HTML node')
                actions.addAndStepInto($createTextNode(mdastNode.value))
            },
        })
    },
})

import { act, cleanup, fireEvent, render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { createRef, type ReactNode } from 'react'
import { AppThemeContext } from '../../theme/theme_context'
import { AppThemeProvider } from '../../theme/theme_provider'
import { ACTION_PROMPT_PLACEHOLDERS } from '../../data/action_placeholders'
import { dialogService } from '../../services/dialog_service'
import { THEME_MODE_STORAGE_KEY } from '../../theme/use_theme_settings'
import { MARKDOWN_STYLE_PRESETS } from '../../theme/theme_config'
import { useAppTheme } from '../../theme/use_app_theme'
import { MarkdownEditor, type MarkdownEditorHandle } from './markdown_editor'
import { MarkdownDocumentHistoryStore } from './markdown_document_history_store'
import { flushMarkdownEditors } from './markdown_editor_flush'
import { buildMarkdownContentSx } from './markdown_style_sx'
import {
    MarkdownDataSourceBase,
    type MarkdownBindingKind,
    type MarkdownDataSource,
    type MarkdownDocumentTarget,
} from './markdown_data_source'
import type { CardOpenDocument } from '../../services/open_files_service'

class TestMarkdownDataSource extends MarkdownDataSourceBase {
    readonly commit = vi.fn<MarkdownDataSource['commit']>(() => true)
    readonly edit = vi.fn()
    private readonly markdownByTarget = new Map<MarkdownDocumentTarget, string>()
    private readonly targets = new Map<string, MarkdownDocumentTarget>()

    getMarkdown(target: MarkdownDocumentTarget) {
        const markdown = this.markdownByTarget.get(target)
        if (markdown === undefined) throw new Error('Unknown test document')
        return markdown
    }

    select(binding: MarkdownBindingKind, identity: string, markdown: string) {
        const target = this.target(identity)
        this.markdownByTarget.set(target, markdown)
        this.setActiveTarget(binding, target)
        return target
    }

    replace(target: MarkdownDocumentTarget, markdown: string, originBinding: MarkdownBindingKind | null = null) {
        this.markdownByTarget.set(target, markdown)
        this.dispatchMarkdownReplaced({ originBinding, target })
    }

    target(identity: string) {
        const existing = this.targets.get(identity)
        if (existing) return existing
        const document = Object.assign(new EventTarget(), { kind: 'card' as const }) as CardOpenDocument
        const target: MarkdownDocumentTarget = { document }
        this.targets.set(identity, target)
        return target
    }
}

function renderEditor(markdown = '') {
    return render(
        <AppThemeProvider>
            <MarkdownEditor markdown={markdown} onChange={vi.fn()} />
        </AppThemeProvider>,
    )
}

function MarkdownEditorWithStyleControl() {
    const { setMarkdownStyle } = useAppTheme()
    const handleSetSerif = () => {
        setMarkdownStyle('serif')
    }

    return (
        <>
            <button onClick={handleSetSerif} type="button">Serif</button>
            <MarkdownEditor markdown="" onChange={vi.fn()} />
        </>
    )
}

function MarkdownContentSxOverride({ children }: { children: ReactNode }) {
    const theme = useAppTheme()
    const value = { ...theme, markdownContentSx: { paddingTop: '37px' } }

    return <AppThemeContext.Provider value={value}>{children}</AppThemeContext.Provider>
}

describe('MarkdownEditor', () => {
    afterEach(() => {
        cleanup()
        window.localStorage.clear()
    })

    it('renders the editing surface seeded with the markdown value', () => {
        renderEditor('# Title\n\nBody')

        expect(screen.getByRole('textbox')).toHaveValue('# Title\n\nBody')
    })

    it('disables MDX and HTML processing', () => {
        renderEditor()

        expect(document.querySelector('[data-html-processing-suppressed="true"]')).not.toBeNull()
    })

    it('reports Markdown parser errors through the dialog service', () => {
        const reportError = vi.spyOn(dialogService, 'error')
        renderEditor()

        fireEvent.click(screen.getByTestId('emit-markdown-error'))

        expect(reportError).toHaveBeenCalledExactlyOnceWith(
            new Error('Invalid Markdown'),
            { fallbackMessage: 'Markdown could not be parsed' },
        )
        reportError.mockRestore()
    })

    it('imports plain clipboard text as markdown', () => {
        const markdown = '# Title\n\n- Item\n\n[Link](https://example.com)\n\n```js\nconst value = 1;\n```'
        renderEditor()

        const pasteHandled = fireEvent.paste(screen.getByRole('textbox'), {clipboardData: {getData: (type: string) => type === 'text/plain' ? markdown : ''}})

        expect(pasteHandled).toBe(false)
        expect(screen.getByRole('textbox')).toHaveValue(markdown)
    })

    it('prefers explicit markdown clipboard content over plain text', () => {
        renderEditor()

        fireEvent.paste(screen.getByRole('textbox'), {clipboardData: {getData: (type: string) => type === 'text/markdown' ? '**Markdown**' : 'Plain text'}})

        expect(screen.getByRole('textbox')).toHaveValue('**Markdown**')
    })

    it('leaves non-text clipboard data to the editor', () => {
        renderEditor()

        const pasteHandled = fireEvent.paste(screen.getByRole('textbox'), {clipboardData: { getData: () => '' }})

        expect(pasteHandled).toBe(true)
        expect(screen.getByRole('textbox')).toHaveValue('')
    })

    it('does not propagate edits while typing', () => {
        const onChange = vi.fn()
        render(
            <AppThemeProvider>
                <MarkdownEditor markdown="original" onChange={onChange} />
            </AppThemeProvider>,
        )

        fireEvent.change(screen.getByRole('textbox'), { target: { value: 'edited' } })

        expect(onChange).not.toHaveBeenCalled()
    })

    it('reports local dirty state without propagating the buffered edit', () => {
        const onChange = vi.fn()
        const onDirtyChange = vi.fn()
        render(
            <AppThemeProvider>
                <MarkdownEditor markdown="original" onChange={onChange} onDirtyChange={onDirtyChange} />
            </AppThemeProvider>,
        )

        fireEvent.change(screen.getByRole('textbox'), { target: { value: 'edited' } })

        expect(onDirtyChange).toHaveBeenLastCalledWith(true)
        expect(onChange).not.toHaveBeenCalled()

        flushMarkdownEditors()
        expect(onDirtyChange).toHaveBeenLastCalledWith(false)
    })

    it('stages data-source edits and keeps commit buffered until flush', () => {
        const dataSource = new TestMarkdownDataSource()
        const target = dataSource.select('list-action', 'prompt', 'original')
        const historyStore = new MarkdownDocumentHistoryStore()
        render(
            <AppThemeProvider>
                <MarkdownEditor
                    binding="list-action"
                    dataSource={dataSource}
                    historyStore={historyStore}
                />
            </AppThemeProvider>,
        )

        fireEvent.change(screen.getByRole('textbox'), { target: { value: 'edited' } })

        expect(dataSource.edit).toHaveBeenCalledExactlyOnceWith('list-action', target, 'edited')
        expect(dataSource.commit).not.toHaveBeenCalled()

        flushMarkdownEditors()
        expect(dataSource.commit).toHaveBeenCalledExactlyOnceWith('list-action', target, 'edited')
    })

    it('keeps a failed editor dirty without blocking another editor flush', () => {
        const failedDataSource = new TestMarkdownDataSource()
        const successfulDataSource = new TestMarkdownDataSource()
        const failedTarget = failedDataSource.select('list-card', 'failed-card', 'failed original')
        const savedTarget = successfulDataSource.select('board-card', 'saved-card', 'saved original')
        failedDataSource.commit.mockReturnValue(false)
        render(
            <AppThemeProvider>
                <MarkdownEditor
                    binding="list-card"
                    dataSource={failedDataSource}
                    historyStore={new MarkdownDocumentHistoryStore()}
                />
                <MarkdownEditor
                    binding="board-card"
                    dataSource={successfulDataSource}
                    historyStore={new MarkdownDocumentHistoryStore()}
                />
            </AppThemeProvider>,
        )
        const [failedEditor, successfulEditor] = screen.getAllByRole('textbox')
        fireEvent.change(failedEditor, { target: { value: 'failed edit' } })
        fireEvent.change(successfulEditor, { target: { value: 'saved edit' } })

        flushMarkdownEditors()

        expect(failedDataSource.commit).toHaveBeenCalledExactlyOnceWith('list-card', failedTarget, 'failed edit')
        expect(successfulDataSource.commit).toHaveBeenCalledExactlyOnceWith('board-card', savedTarget, 'saved edit')
    })

    it('drops the dirty buffer without committing when the binding clears with discard', () => {
        const dataSource = new TestMarkdownDataSource()
        dataSource.select('list-card', 'card-1', 'original')
        render(
            <AppThemeProvider>
                <MarkdownEditor
                    binding="list-card"
                    dataSource={dataSource}
                    historyStore={new MarkdownDocumentHistoryStore()}
                />
            </AppThemeProvider>,
        )
        fireEvent.change(screen.getByRole('textbox'), { target: { value: 'edited' } })

        act(() => dataSource.clearBindings(true))

        expect(dataSource.commit).not.toHaveBeenCalled()
        expect(screen.getByRole('textbox')).toHaveValue('')
    })

    it('keeps the outgoing dirty document active until a failed switch can retry', async () => {
        const dataSource = new TestMarkdownDataSource()
        const editorRef = createRef<MarkdownEditorHandle>()
        dataSource.select('list-card', 'first-card', 'first original')
        dataSource.commit.mockReturnValue(false)
        render(
            <AppThemeProvider>
                <MarkdownEditor
                    binding="list-card"
                    dataSource={dataSource}
                    historyStore={new MarkdownDocumentHistoryStore()}
                    ref={editorRef}
                />
            </AppThemeProvider>,
        )
        fireEvent.change(screen.getByRole('textbox'), { target: { value: 'first edited' } })

        act(() => dataSource.select('list-card', 'second-card', 'second original'))

        expect(editorRef.current?.getMarkdown()).toBe('first edited')

        dataSource.commit.mockReturnValue(true)
        await act(async () => {
            flushMarkdownEditors()
            await Promise.resolve()
        })

        expect(screen.getByRole('textbox')).toHaveValue('second original')
    })

    it('keeps the origin editor intact while synchronizing another binding for the same document', () => {
        const dataSource = new TestMarkdownDataSource()
        const boardEditorRef = createRef<MarkdownEditorHandle>()
        const listEditorRef = createRef<MarkdownEditorHandle>()
        const sharedTarget = dataSource.select('board-card', 'shared-card', 'original')
        dataSource.select('list-card', 'shared-card', 'original')
        dataSource.commit.mockImplementation((binding, target, markdown) => {
            dataSource.replace(target, markdown, binding)
            return true
        })
        render(
            <AppThemeProvider>
                <MarkdownEditor
                    binding="board-card"
                    dataSource={dataSource}
                    historyStore={new MarkdownDocumentHistoryStore()}
                    ref={boardEditorRef}
                />
                <MarkdownEditor
                    binding="list-card"
                    dataSource={dataSource}
                    historyStore={new MarkdownDocumentHistoryStore()}
                    ref={listEditorRef}
                />
            </AppThemeProvider>,
        )
        const [boardEditor] = screen.getAllByRole('textbox')
        fireEvent.change(boardEditor, { target: { value: 'board edit' } })

        flushMarkdownEditors()

        expect(dataSource.commit).toHaveBeenCalledExactlyOnceWith('board-card', sharedTarget, 'board edit')
        expect(boardEditorRef.current?.getMarkdown()).toBe('board edit')
        expect(listEditorRef.current?.getMarkdown()).toBe('board edit')
    })

    it('flushes a data-source edit on blur only when requested', () => {
        const dataSource = new TestMarkdownDataSource()
        const target = dataSource.select('list-action', 'prompt', 'original')
        const historyStore = new MarkdownDocumentHistoryStore()
        render(
            <AppThemeProvider>
                <MarkdownEditor
                    binding="list-action"
                    dataSource={dataSource}
                    flushOnBlur
                    historyStore={historyStore}
                />
            </AppThemeProvider>,
        )
        const editor = screen.getByRole('textbox')
        fireEvent.focus(editor)
        fireEvent.change(editor, { target: { value: 'edited' } })

        fireEvent.blur(editor)

        expect(dataSource.commit).toHaveBeenCalledExactlyOnceWith('list-action', target, 'edited')
    })

    it('keeps default data-source edits buffered on blur', () => {
        const dataSource = new TestMarkdownDataSource()
        dataSource.select('list-card', 'card', 'original')
        const historyStore = new MarkdownDocumentHistoryStore()
        render(
            <AppThemeProvider>
                <MarkdownEditor
                    binding="list-card"
                    dataSource={dataSource}
                    historyStore={historyStore}
                />
            </AppThemeProvider>,
        )
        const editor = screen.getByRole('textbox')
        fireEvent.focus(editor)
        fireEvent.change(editor, { target: { value: 'edited' } })

        fireEvent.blur(editor)

        expect(dataSource.commit).not.toHaveBeenCalled()
    })

    it('replaces matching active content from a non-origin source event', () => {
        const dataSource = new TestMarkdownDataSource()
        dataSource.select('list-action', 'prompt', 'original')
        const historyStore = new MarkdownDocumentHistoryStore()
        render(
            <AppThemeProvider>
                <MarkdownEditor
                    binding="list-action"
                    dataSource={dataSource}
                    historyStore={historyStore}
                />
            </AppThemeProvider>,
        )

        act(() => dataSource.replace(dataSource.target('prompt'), 'external'))

        expect(screen.getByRole('textbox')).toHaveValue('external')
        expect(dataSource.commit).not.toHaveBeenCalled()
        expect(historyStore.canUndo).toBe(false)
        expect(historyStore.canRedo).toBe(false)
    })

    it('does not report editor-normalized markdown as a user edit', () => {
        const onChange = vi.fn()
        const onDirtyChange = vi.fn()
        const { unmount } = render(
            <AppThemeProvider>
                <MarkdownEditor markdown="original  \n" onChange={onChange} onDirtyChange={onDirtyChange} />
            </AppThemeProvider>,
        )

        expect(onDirtyChange).not.toHaveBeenCalledWith(true)
        unmount()

        expect(onChange).not.toHaveBeenCalled()
    })

    it('flushes pending edits through onChange on unmount', () => {
        const onChange = vi.fn()
        const { unmount } = render(
            <AppThemeProvider>
                <MarkdownEditor markdown="original" onChange={onChange} />
            </AppThemeProvider>,
        )

        fireEvent.change(screen.getByRole('textbox'), { target: { value: 'edited' } })
        unmount()

        expect(onChange).toHaveBeenCalledExactlyOnceWith('edited')
    })

    it('flushes pending edits when the app-level flush runs', () => {
        const onChange = vi.fn()
        render(
            <AppThemeProvider>
                <MarkdownEditor markdown="original" onChange={onChange} />
            </AppThemeProvider>,
        )

        fireEvent.change(screen.getByRole('textbox'), { target: { value: 'edited' } })
        flushMarkdownEditors()

        expect(onChange).toHaveBeenCalledExactlyOnceWith('edited')
    })

    it('does not flush again when the content did not change since the last flush', () => {
        const onChange = vi.fn()
        const { unmount } = render(
            <AppThemeProvider>
                <MarkdownEditor markdown="original" onChange={onChange} />
            </AppThemeProvider>,
        )

        fireEvent.change(screen.getByRole('textbox'), { target: { value: 'edited' } })
        flushMarkdownEditors()
        unmount()

        expect(onChange).toHaveBeenCalledExactlyOnceWith('edited')
    })

    it('renders the formatting toolbar inside the markdown editor', () => {
        renderEditor()

        expect(screen.getByTestId('mdx-editor')).toContainElement(screen.getByTestId('mdx-editor-toolbar'))
    })

    it('omits the toolbar when hideToolbar is set', () => {
        render(
            <AppThemeProvider>
                <MarkdownEditor hideToolbar markdown="" onChange={vi.fn()} />
            </AppThemeProvider>,
        )

        expect(screen.queryByTestId('mdx-editor-toolbar')).not.toBeInTheDocument()
    })

    it('reports live edits through onLiveChange while buffering onChange', () => {
        const onChange = vi.fn()
        const onLiveChange = vi.fn()
        render(
            <AppThemeProvider>
                <MarkdownEditor markdown="original" onChange={onChange} onLiveChange={onLiveChange} />
            </AppThemeProvider>,
        )

        fireEvent.change(screen.getByRole('textbox'), { target: { value: 'edited' } })

        expect(onLiveChange).toHaveBeenLastCalledWith('edited')
        expect(onChange).not.toHaveBeenCalled()
    })

    it('renders read-only when requested', () => {
        render(
            <AppThemeProvider>
                <MarkdownEditor markdown="locked" onChange={vi.fn()} readOnly />
            </AppThemeProvider>,
        )

        expect(screen.getByRole('textbox')).toHaveAttribute('readonly')
    })

    it('does not infer read-only state from an empty data-source binding', () => {
        render(
            <AppThemeProvider>
                <MarkdownEditor
                    binding="list-card"
                    dataSource={new TestMarkdownDataSource()}
                    historyStore={new MarkdownDocumentHistoryStore()}
                />
            </AppThemeProvider>,
        )

        expect(screen.getByRole('textbox')).not.toHaveAttribute('readonly')
    })

    it('shows placeholder insertion only when placeholders are configured', () => {
        const view = render(
            <AppThemeProvider>
                <MarkdownEditor markdown="" onChange={vi.fn()} placeholders={ACTION_PROMPT_PLACEHOLDERS} />
            </AppThemeProvider>,
        )

        expect(screen.getByRole('button', { name: 'Insert placeholder' })).toBeInTheDocument()

        view.rerender(
            <AppThemeProvider>
                <MarkdownEditor markdown="" onChange={vi.fn()} />
            </AppThemeProvider>,
        )

        expect(screen.queryByRole('button', { name: 'Insert placeholder' })).not.toBeInTheDocument()
    })

    it('uses the MDXEditor palette matching the app theme', () => {
        window.localStorage.setItem(THEME_MODE_STORAGE_KEY, 'dark')

        renderEditor()

        expect(screen.getByTestId('mdx-editor')).toHaveClass('dark-theme')
    })

    it('marks the toolbar sticky by default', () => {
        const { container } = render(
            <AppThemeProvider>
                <MarkdownEditor markdown="" onChange={vi.fn()} />
            </AppThemeProvider>,
        )

        expect(container.querySelector('[data-sticky-toolbar="true"]')).not.toBeNull()
    })

    it('maps markdown sections to scoped content selectors', () => {
        const styleSx = buildMarkdownContentSx(MARKDOWN_STYLE_PRESETS.handwritten)

        expect(styleSx).toMatchObject({
            '& .mdxeditor-content h1': {
                fontFamily: MARKDOWN_STYLE_PRESETS.handwritten.title1.fontFamily,
                fontSize: MARKDOWN_STYLE_PRESETS.handwritten.title1.fontSize,
                fontStyle: 'normal',
                fontWeight: 700,
                textDecoration: 'none',
            },
            '& .mdxeditor-content p': {
                fontFamily: MARKDOWN_STYLE_PRESETS.handwritten.body.fontFamily,
                fontSize: MARKDOWN_STYLE_PRESETS.handwritten.body.fontSize,
            },
            '& .mdxeditor-content a': {textDecoration: 'underline'},
            '& .mdxeditor-content blockquote, & .mdxeditor-content blockquote p': {
                fontFamily: MARKDOWN_STYLE_PRESETS.handwritten.blockquote.fontFamily,
                fontSize: MARKDOWN_STYLE_PRESETS.handwritten.blockquote.fontSize,
                fontStyle: 'italic',
            },
            '& .mdxeditor-content :not(pre) > code': {fontFamily: MARKDOWN_STYLE_PRESETS.handwritten.inlineCode.fontFamily},
            '& .mdxeditor-content pre, & .mdxeditor-content pre code': {fontFamily: MARKDOWN_STYLE_PRESETS.handwritten.codeBlock.fontFamily},
            '& .mdxeditor-content table, & .mdxeditor-content th, & .mdxeditor-content td': {fontFamily: MARKDOWN_STYLE_PRESETS.handwritten.table.fontFamily},
        })
    })

    it('updates editor styles when the markdown preset changes', () => {
        const { container } = render(
            <AppThemeProvider>
                <MarkdownEditorWithStyleControl />
            </AppThemeProvider>,
        )
        const editorWrapper = container.querySelector('[data-sticky-toolbar="true"]')
        const initialClassName = editorWrapper?.className

        fireEvent.click(screen.getByRole('button', { name: 'Serif' }))

        expect(editorWrapper?.className).not.toBe(initialClassName)
    })

    it('uses the derived Markdown style provided by the app theme', () => {
        const { container } = render(
            <AppThemeProvider>
                <MarkdownContentSxOverride>
                    <MarkdownEditor markdown="" onChange={vi.fn()} />
                </MarkdownContentSxOverride>
            </AppThemeProvider>,
        )

        expect(container.querySelector('[data-sticky-toolbar="true"]')).toHaveStyle({ paddingTop: '37px' })
    })
})

